class Solution {
    public int maxCount(int m,int n,int[][] ops){
        int rows=m,columns=n;
        for(int[] operation:ops){
            rows=Math.min(rows,operation[0]);
            columns=Math.min(columns,operation[1]);
        }
        return rows*columns;
    }
}

code.kotlin:
class Solution {
    fun maxCount(m:Int,n:Int,ops:Array<IntArray>):Int{
        var rows=m;
        var columns=n;
        for(operation in ops){
            rows=minOf(rows,operation[0]);
            columns=minOf(columns,operation[1])
        };
        return rows*columns
    }
}

